package com.bank.hr.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates all size-K auditor committees from a pool of N via backtracking.
public class CommitteeService {
    private static final Logger log = Logger.getLogger(CommitteeService.class.getName());

    public List<List<Integer>> allCommittees(int n, int k) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(n, k, 1, new ArrayList<>(), result);
        log.info(() -> "Generated " + result.size() + " committees of size " + k);
        return result;
    }

    private void backtrack(int n, int k, int start,
                           List<Integer> current, List<List<Integer>> result) {
        if (current.size() == k) {
            result.add(new ArrayList<>(current)); // complete committee: copy
            log.fine(() -> "Formed committee " + current);
            return;
        }
        // Prune: stop when too few auditors remain to fill the committee.
        int need = k - current.size();
        for (int i = start; i <= n - need + 1; i++) {
            current.add(i);                 // choose auditor i
            backtrack(n, k, i + 1, current, result); // strictly increasing
            current.remove(current.size() - 1);      // backtrack
        }
    }
}
